CREATE POLICY "recipe_videos_read" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'recipe-videos');
CREATE POLICY "recipe_videos_admin_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'recipe-videos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "recipe_videos_admin_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'recipe-videos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "recipe_videos_admin_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'recipe-videos' AND public.has_role(auth.uid(), 'admin'));